const input = $input.first().json;

const rawText =
  input.chatInput ||
  input.message?.text ||
  input.text ||
  '';

const text = rawText.replace(/`/g, '');

const triggerSource = input.message?.text
  ? 'telegram'
  : (input.chatInput ? 'chat' : 'direct');

const telegramChatId = input.message?.chat?.id || null;

const urlRegex = /https?:\/\/[^\s<>"'\)\]]+/g;
const allUrls = text.match(urlRegex) || [];

const feeds = allUrls
  .map(u => u.replace(/[,;`]+$/, '').trim())
  .filter(u => u.length > 10)
  .map(url => ({
    label: url,
    url,
    source: url,
    group: 'Из чата',
    triggerSource,
    telegramChatId
  }));

if (feeds.length === 0) {
  return [{
    json: {
      error: 'Не найдено ни одного URL в сообщении',
      report: 'Не найдено ни одного URL в сообщении',
      triggerSource,
      telegramChatId
    }
  }];
}

return feeds.map(f => ({ json: f }));

const items = $input.all();
const now = Date.now();
const CUTOFF_DAYS = 100;
const healthy = [];
const problematic = [];

function escapeHtml(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function shortUrl(url) {
  try {
    const u = new URL(url);
    const path = u.pathname.length > 30 ? u.pathname.substring(0, 30) + '…' : u.pathname;
    return u.hostname + path;
  } catch (e) {
    return String(url || '').substring(0, 50);
  }
}

function shortReason(raw) {
  if (!raw) return 'Ошибка';
  const s = String(raw);
  const codeMatch = s.match(/^(\d{3})/);
  if (codeMatch) return codeMatch[1];
  if (/cloudflare|blocked/i.test(s)) return 'Cloudflare';
  if (/empty/i.test(s)) return 'Пусто';
  if (/timeout/i.test(s)) return 'Таймаут';
  if (/no items/i.test(s)) return 'Нет записей';
  if (/date/i.test(s)) return 'Дата';
  return s.replace(/<[^>]*>/g, '').substring(0, 30);
}

function toChunks(text) {
  const lines = text.split('\n');
  const chunks = [];
  let cur = '';
  for (const line of lines) {
    if ((cur + '\n' + line).length > 3800) {
      if (cur) chunks.push(cur);
      cur = line;
    } else {
      cur += (cur ? '\n' : '') + line;
    }
  }
  if (cur) chunks.push(cur);
  return chunks;
}

const metaItems = $('🔍 Extract URLs from Text').all();
const firstMeta = metaItems[0]?.json || {};
const triggerSource = firstMeta.triggerSource || 'direct';
const telegramChatId = firstMeta.telegramChatId || null;

if (firstMeta.error) {
  return [{
    json: {
      report: firstMeta.report || firstMeta.error,
      triggerSource,
      telegramChatId
    }
  }];
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const meta = metaItems[i] ? metaItems[i].json : { url: '' };
  const url = meta.url || '';

  let xml = item.json.data || item.json.body || '';
  let fetchError = item.json.error ? (item.json.error.message || 'HTTP Error') : null;

  if (fetchError || !xml || xml.length < 50 || /<html/i.test(xml)) {
    const raw = fetchError || (xml.length < 50 ? 'empty' : 'blocked');
    problematic.push({ url, reason: shortReason(raw) });
    continue;
  }

  const isAtom = /<entry/i.test(xml);
  const blockM = isAtom
    ? xml.match(/<entry[^>]*>([\s\S]*?)<\/entry>/i)
    : xml.match(/<item[^>]*>([\s\S]*?)<\/item>/i);

  if (!blockM) {
    problematic.push({ url, reason: 'Нет записей' });
    continue;
  }

  const dateM = blockM[1].match(/<(pubDate|published|updated)>([\s\S]*?)<\//i);
  const ts = dateM ? Date.parse(dateM[2].replace(/<!\[CDATA\[|\]\]>/g, '').trim()) : NaN;

  if (isNaN(ts)) {
    problematic.push({ url, reason: 'Дата' });
    continue;
  }

  const days = Math.floor((now - ts) / 86400000);

  if (days <= CUTOFF_DAYS && days >= 0) {
    healthy.push({ url, days });
  } else {
    problematic.push({ url, reason: `${days}д` });
  }
}

const healthyLines = healthy
  .sort((a, b) => a.days - b.days)
  .map(h => `✅ ${h.days}д — ${escapeHtml(shortUrl(h.url))}`);

const badLines = problematic
  .map(p => `❌ ${escapeHtml(p.reason)} — ${escapeHtml(shortUrl(p.url))}`);

const msg1 = `✅ <b>Рабочие (${healthy.length})</b>\n` + (healthyLines.length ? healthyLines.join('\n') : 'Нет рабочих лент');
const msg2 = `❌ <b>Проблемные (${problematic.length})</b>\n` + (badLines.length ? badLines.join('\n') : 'Все ленты в порядке!');

const results = [];
for (const chunk of toChunks(msg1)) {
  results.push({
    json: {
      report: chunk,
      triggerSource,
      telegramChatId
    }
  });
}
for (const chunk of toChunks(msg2)) {
  results.push({
    json: {
      report: chunk,
      triggerSource,
      telegramChatId
    }
  });
}

return results;

return $input.all().map(item => ({
  json: {
    report: item.json.report,
    triggerSource: item.json.triggerSource,
    telegramChatId: item.json.telegramChatId || null
  }
}));
